pub const LIMIT: u32 = 3;

pub fn larger<T: Ord>(a: T, b: T) -> T {
    a.max(b)
}

pub fn top(a: u32, b: u32) -> u32 {
    larger(a, b).min(LIMIT)
}

pub fn count(items: &[u32]) -> u32 {
    let mut total = 0;
    for item in items {
        if *item > LIMIT && total < 10 {
            total += 1;
        }
    }
    total
}
